/* Quote rejection and explicit audited cancellation; financial records are retained. */
stages.push(['cancelled','Cancelled jobs','Cancelled requests retained for reference']);
const stageBeforeCancellation=jobStage;jobStage=function(j){return j.status==='Cancelled'?'cancelled':stageBeforeCancellation(j)};
const actionBeforeCancellation=nextAction;nextAction=function(j){return j.status==='Cancelled'?'Cancelled · '+(j.cancellation?.reason||'See job history'):actionBeforeCancellation(j)};
function rejectedQuote(j){return j?.quotes?.at(-1)?.status==='Rejected'}
function rejectQuoteForm(jid,qid){const j=getJob(jid),q=j?.quotes.find(q=>q.id===qid);if(role!=='manager'||!j||!canSeeProperty(property(j.property))||q?.status!=='Pending'||['Scheduled','In progress','Completed','Cancelled'].includes(j.status))return;openForm('Reject quote.',`<p>Reject this quote if the proposed work will not proceed. To change the price or scope, use Request revision instead.</p><label>Reason for rejection</label><textarea name="reason" required maxlength="2000" rows="3"></textarea>`,'Reject quote',async d=>{const reason=String(d.get('reason')||'').trim();if(!reason)return;if(await commit(()=>{q.status='Rejected';q.rejectedAt=now();q.rejectedBy=person();q.rejectionReason=reason;j.status='New';j.opsAction='quoting';addEvent(j,'Quote rejected',reason);j.history.push('Quote rejected by '+person()+': '+reason)})){render();jobDetail(jid,'quotes')}})}
function cancelRejectedJobForm(jid){const j=getJob(jid);if(role!=='sevlink'||!rejectedQuote(j)||['Cancelled','Completed','In progress'].includes(j.status))return;openForm('Cancel job after rejected quote.',`<p><b>${esc(j.ref)} · ${esc(j.title)}</b></p><label>Cancellation reason</label><textarea name="reason" required maxlength="2000" rows="3">${esc(j.quotes.at(-1).rejectionReason||'Quote rejected by property manager.')}</textarea><div class="notice">The job leaves the active pipeline. Its quotes, reports, invoices and payment records remain available. Cancellation does not refund or write off any balance.</div>`,'Cancel job',async d=>{if(await cancelRejectedJob(jid,d.get('reason'))){render();jobDetail(jid,'history');toast('Job cancelled and retained in Cancelled jobs.')}})}
async function cancelRejectedJob(jid,reason){const j=getJob(jid);if(role!=='sevlink'||!j||!rejectedQuote(j)||!String(reason||'').trim()||['Cancelled','Completed','In progress'].includes(j.status)||j.quotes.some(q=>q.status==='Approved'||q.status==='Pending'))return false;return commit(()=>{j.cancellation={at:now(),by:person(),reason:String(reason).trim(),previousStatus:j.status,previousSchedule:j.schedule};j.status='Cancelled';j.schedule=null;j.opsAction=null;for(const b of state.privateBookings.filter(b=>b.job===jid&&!['Attended','Cancelled','Declined'].includes(b.status))){b.status='Cancelled';b.log??=[];b.log.push({at:now(),text:'Job cancelled after rejected quote.'})}j.history.push('Job cancelled by '+person()+': '+j.cancellation.reason);addEvent(j,'Job cancelled',j.cancellation.reason);notify(j,'Job cancelled',j.ref+': '+j.cancellation.reason)})}
const quotesBeforeCancellation=renderQuotes;renderQuotes=function(j){quotesBeforeCancellation(j);if(role==='manager'&&j.status!=='Cancelled')for(const q of j.quotes.filter(q=>q.status==='Pending'))$('#jobcontent').insertAdjacentHTML('beforeend',`<button class="secondary" onclick="rejectQuoteForm('${j.id}','${q.id}')">Reject quote · ${money(q.amount)}</button>`)};
const detailBeforeCancellation=jobDetail;jobDetail=function(jid,section='comments'){detailBeforeCancellation(jid,section);const j=getJob(jid);if(!j)return;if(j.status==='Cancelled'){$('#jobcontent').insertAdjacentHTML('afterbegin',`<div class="notice"><b>Job cancelled</b><p>${esc(j.cancellation?.reason||'Cancelled')}<br>${esc(j.cancellation?.by||'')} · ${date(j.cancellation?.at)}</p></div>`);modal.querySelectorAll('[onclick*="bookingForm"],[onclick*="editJob"],[onclick*="quoteForm"],#uploadQuote,#assign,#complete').forEach(b=>b.remove())}else if(role==='sevlink'&&rejectedQuote(j)&&!j.quotes.some(q=>['Pending','Approved'].includes(q.status)))$('#jobcontent').insertAdjacentHTML('afterbegin',`<div class="notice"><b>Property manager rejected the quote.</b><p>${esc(j.quotes.at(-1).rejectionReason||'')}</p><button class="secondary" onclick="cancelRejectedJobForm('${j.id}')">Cancel job</button></div>`)};
const approvedBeforeCancellation=approved;approved=function(j){return j?.status==='Cancelled'?false:approvedBeforeCancellation(j)};
const bookingSaveBeforeCancellation=savePrivateBooking;savePrivateBooking=async function(bid,record){if(getJob(record.job)?.status==='Cancelled')return false;return bookingSaveBeforeCancellation(bid,record)};
const scheduleSaveBeforeCancellation=saveSchedule;saveSchedule=async function(jid,...args){if(getJob(jid)?.status==='Cancelled')return false;return scheduleSaveBeforeCancellation(jid,...args)};
const quoteFormBeforeCancellation=quoteForm;quoteForm=function(jid){if(getJob(jid)?.status==='Cancelled')return;return quoteFormBeforeCancellation(jid)};
startup();
